

    const sampleBooks = {"laut": {"title": "Wenn alles gleichzeitig laut ist", "pages": [{"src": "material/leseproben/laut-1.webp", "number": 1, "text": "Wenn alles gleichzeitig laut ist.\nWas gerade in mir los ist\nEin stiller Ort zwischen Zusammenbruch & Kaffee."}, {"src": "material/leseproben/laut-2.webp", "number": 2, "text": "Du musst hier nichts leisten.\nAlles, was im Kopf tobt, rausziehen.\nSammeln. Entleeren. Sichtbar machen.\nDieses Workbook ist für Momente, in denen dein Kopf\nzu voll ist – nicht für später, sondern für jetzt.\nDieses Workbook ist ein Selbstfürsorge -Guide und ersetzt  keine Therapie."}, {"src": "material/leseproben/laut-3.webp", "number": 3, "text": "Dieses Workbook ist kein Plan, den du erfüllen musst.\nEs ist ein Ort.\nDieses Workbook ist entstanden,\nweil mir genau solche Seiten selbst geholfen haben.\nIn Momenten, in denen mein Kopf zu laut war und ich etwas\ngebraucht habe, das nichts von mir verlangt.\nDu musst dieses Worrkbook nicht durcharbeiten.\nDu darfst Seiten überspringen.\nPausieren.\nZurückkehren.\nEs gibt hier kein richtig oder falsch.\nVielleicht schreibst du viel,\nvielleicht nur ein Wort,\nvielleicht auch garnichts,\nall das ist auch so okay.\nWenn Gefühle auftauchen, die du sonst wegschiebst, ist\ndas kein Rückschritt.\nEs ist dein Nervensystem,\ndas vorsichtig Vertrauen fasst.\nZwischen Zusammenbruch und Kaffee bist du immer noch du.\nMit deinem Innenleben"}, {"src": "material/leseproben/laut-4.webp", "number": 4, "text": "Der emotionale Dampfablass\nDie Seite , wo alles ungefiltert raus darf.\nNoch kein Ordnen,. Kein Sortiere. Kein Filtern.\n"}, {"src": "material/leseproben/laut-5.webp", "number": 5, "text": "Alles was gerade da ist.\nHier gilt nicht Leistung, sondern Ehrlichkeit.\nWas ist gerade a, Lautesten?\n(Egal wie groß, wie klein, hier darf alles sein)\n"}, {"src": "material/leseproben/laut-6.webp", "number": 6, "text": "Hier geht es nur ums Hinsehen, nicht ums Lösen.\nDas tut weh\nWas in dem, was ich eben geschrieben habe, fühlt sich am\nschwersten an?\nDas macht Stress\nWas davon zieht gerade meine Energie?\nWas davon muss ich nicht jetzt lösen?\nWas kann ich heute liegen lassen?\nWas davon braucht gerade etwas von mir?"}]}, "verliere": {"title": "Wenn ich mich irgendwo verliere", "pages": [{"src": "material/leseproben/verliere-1.webp", "number": 1, "text": "Wenn ich mich irgendwo verliere\nZwischen Funktionieren und innerem Abstand\nEin stiller Ort zwischen Zusammenbruch & Kaffee."}, {"src": "material/leseproben/verliere-2.webp", "number": 2, "text": "Du musst hier nichts leisten.\nDieses Workbook ist ein Selbstfürsorge -Guide und ersetzt  keine Therapie.\nDu musst nichts lösen.\nNichts analysieren.\nNichts “richtig” machen.\nHier geht es nicht um Veränderung. \nHier geht es um Verbindung."}, {"src": "material/leseproben/verliere-3.webp", "number": 3, "text": "Zwischen Zusammenbruch und Kaffee bist du immer noch du.\nMit deinem Innenleben\nDieses Workbook ist kein Ratgeber\n.\nEs ist kein Plan zur Selbstoptimierung.\n Keine Anleitung, wie man „richtig funktioniert“.\nDieses Workbook ist eine Einladung.\nEine Einladung, sich selbst ehrlicher zu begegnen.\n Eigene Muster zu erkennen.\n Innere Prozesse besser zu verstehen.\nDu musst hier nichts perfekt machen.\n Du musst nichts „richtig“ beantworten.\nDieses Workbook ist kein Test.\nEs ist ein Raum."}, {"src": "material/leseproben/verliere-4.webp", "number": 4, "text": "Es passiert nicht plötzlich.\nNicht mit einem Knall.\n Nicht mit einem Drama.\nSondern leise.\nFast unbemerkt.\nMan kümmert sich.\n Man reagiert.\n Man funktioniert.\nMan ist da. Für alle.\nUnd während man versucht, allem gerecht zu werden,\n verschiebt sich etwas ganz langsam im Hintergrund:\nDie eigenen Bedürfnisse werden leiser.\nNicht weg.\nAber leiser.\nBis irgendwann dieses schwer greifbare Gefühl auftaucht:\nIrgendwie fühlt sich alles… komisch an.\n"}, {"src": "material/leseproben/verliere-5.webp", "number": 5, "text": "Der leise Abstand zu mir selbst\nWenn ich mich selbst kaum noch erreiche.\nSich selbst fremd zu werden fühlt sich selten dramatisch an.\nEs zeigt sich oft als:\nErschöpfung.\n Reizbarkeit.\n Unruhe.\n Leerer Abstand.\nMan funktioniert weiterhin.\nAber innerlich entsteht ein kaum sichtbarer Abstand:\nZwischen dem, was man tut –\n und dem, was man eigentlich bräuchte.\n"}, {"src": "material/leseproben/verliere-6.webp", "number": 6, "text": "Hier geht es nur ums Hinsehen, nicht ums Lösen.\nWann hatte ich zuletzt das Gefühl, nicht ganz bei mir zu sein?\nErste Annäherung\nWie hat sich das bemerkbar gemacht?\nWie habe ich mich dabei gefühlt?"}]}, "autopilot": {"title": "Wenn mein Autopilot mein Leben steuert", "pages": [{"src": "material/leseproben/autopilot-1.webp", "number": 1, "text": "Wenn mein Autopilot mein Leben steuert\nWarum wir immer wieder gleich reagieren – und wie wir beginnen\nkönnen, bewusst anders zu handeln\nEin Workbook zum Erkennen alter Muster und zum Entdecken neuer Wege\n"}, {"src": "material/leseproben/autopilot-2.webp", "number": 2, "text": "Dieses Workbook ist ein Selbstfürsorge -Guide und ersetzt  keine Therapie.\nDu musst hier nichts leisten.\nDieses Workbook ist kein Test.\n Es geht nicht darum, etwas richtig zu machen.\n Und auch nicht darum, dich sofort zu verändern.\nHier geht es nur um eines:\nVerstehen.\nZwischen Zusammenbruch und Kaffee bist du immer noch du.\nInnenlebenMit deinem\nDu musst hier nichts perfekt machen.\n Du musst nichts „richtig“ beantworten."}, {"src": "material/leseproben/autopilot-3.webp", "number": 3, "text": "Viele unserer Reaktionen entstehen nicht bewusst.\n Sie passieren automatisch – wie ein innerer Autopilot.\nWir reagieren, bevor wir überhaupt merken,\n dass etwas in uns ausgelöst wurde.\nDas bedeutet nicht, dass mit dir etwas falsch ist.\nEs bedeutet nur,\n dass dein System gelernt hat,\n dich auf eine bestimmte Weise zu schützen.\nIn diesem Workbook geht es nicht darum,\n diesen Autopiloten sofort auszuschalten.\nEs geht darum, ihn kennenzulernen.\nDenn erst wenn wir verstehen,\n warum wir reagieren, wie wir reagieren,\n entsteht überhaupt die Möglichkeit,\n irgendwann anders zu handeln.\nBis dahin reicht erst einmal eines:\nNeugierig sein.\n"}, {"src": "material/leseproben/autopilot-7.webp", "number": 7, "text": "Die Momente, in denen der\nAutopilot übernimmt\nDer Autopilot zeigt sich oft nicht laut.\n Er beginnt meist ganz leise.\nManchmal merkt man nur,\n dass eine Situation plötzlich stärker wirkt,\n als sie eigentlich ist.\nEin Satz bleibt im Kopf hängen.\n Ein Blick verunsichert.\n Eine kleine Situation löst plötzlich große Gefühle aus.\nMan reagiert schneller, als man eigentlich möchte.\nVielleicht wird man still.\n Vielleicht zieht man sich zurück.\n Vielleicht entstehen Wut, Zweifel oder Unsicherheit."}, {"src": "material/leseproben/autopilot-8.webp", "number": 8, "text": "Oft tauchen auch Gedanken auf wie:\n„Habe ich etwas falsch gemacht?“\n „Warum passiert mir das immer wieder?“\n „Warum reagiere ich schon wieder so?“\nManchmal merkt man erst später,\n dass die eigene Reaktion größer war\n als die Situation selbst.\nGenau in solchen Momenten\n kann der Autopilot aktiv sein.\nNicht, weil etwas falsch läuft.\n Sondern weil das eigene System versucht,\n auf eine vertraute Weise zu reagieren.\nDer erste Schritt ist deshalb nicht, etwas zu verändern.\nDer erste Schritt ist nur:\nEs wahrzunehmen.\nMuster beginnen sich oft genau in dem Moment zu zeigen,\n in dem man sie zum ersten Mal bemerkt."}, {"src": "material/leseproben/autopilot-9.webp", "number": 9, "text": "Den Autopiloten näher kennenlernen\nErste Begegnung mit dem Autopiloten\nManchmal zeigt sich der Autopilot\n erst im Nachhinein.\nEine Situation ist vorbei.\n Und erst später fällt auf,\n dass eine Reaktion stärker war\n als die Situation selbst.\nDiese Seite lädt dazu ein,\n einen solchen Moment einmal näher anzuschauen.\nHier geht es nur ums Hinsehen, nicht ums Lösen."}]}, "alarm": {"title": "Wenn das eigene System Alarm schlägt", "pages": [{"src": "material/leseproben/alarm-1.webp", "number": 1, "text": "Wenn das eigene System Alarm schlägt\nWenn Dynamiken anfangen zu Erschöpfen,\nund wir beginnen, die Signale unseres eigenen Systems\nwahrzunehmen.\nEin Workbook zum Erkennen innerer Alarmzeichen und zum Verstehen\nerschöpfender Dynamiken."}, {"src": "material/leseproben/alarm-2.webp", "number": 2, "text": "Du musst hier nichts leisten.\nDieses Workbook ist kein Test.\nEs geht nicht darum, etwas sofort zu lösen.\n Und auch nicht darum, dich perfekt im Griff zu haben.\nHier geht es nur um eines:\nWahrnehmen.\nZu bemerken,\n wann dein inneres System beginnt, Alarm zu schlagen.\nZu erkennen,\n wenn Dynamiken anfangen Kraft zu ziehen.\nDu musst hier nichts perfekt machen.\n Du musst nichts „richtig“ beantworten.\nZwischen Zusammenbruch und Kaffee bist du immer noch du.\nInnenlebenMit deinem\nDieses Workbook ist ein Selbstfürsorge -Guide und ersetzt  keine Therapie."}, {"src": "material/leseproben/alarm-3.webp", "number": 3, "text": "Es beginnt selten plötzlich.\nNicht mit einem großen Zusammenbruch.\n Nicht mit einem klaren Warnsignal\nSondern leise.\nAls innere Unruhe.\n Als Anspannung.\n Als dieses schwer greifbare Gefühl von:\n„Irgendetwas stimmt gerade nicht.“\nDas innere System registriert oft viel früher,\n wenn etwas zu viel wird.\nWenn Dynamiken beginnen, Kraft zu ziehen.\n Wenn Grenzen langsam überschritten werden.\n Wenn Erwartungen, Druck oder Konflikte sich aufbauen.\nDoch diese Signale werden leicht übergangen.\nMan funktioniert weiter.\n Man erklärt es sich weg.\n Man passt sich an."}, {"src": "material/leseproben/alarm-4.webp", "number": 4, "text": "Bis das innere System irgendwann deutlicher reagiert.\nNicht, weil es übertreibt.\n Sondern weil es versucht, aufmerksam zu machen.\nDiese Seiten laden dazu ein,\n diese Signale einmal genauer anzuschauen.\nNicht um sofort etwas zu verändern.\nSondern um zu verstehen,\n was das eigene System vielleicht schon längst bemerkt hat."}, {"src": "material/leseproben/alarm-5.webp", "number": 5, "text": "Mein inneres Früh-Warn-System\nWie sich erste Signale zeigen können\nDas innere System meldet sich selten mit klaren Worten.\nEs spricht über Reaktionen.\nÜber Körper.\n Über Gefühle.\n Über kleine Veränderungen im Verhalten."}, {"src": "material/leseproben/alarm-6.webp", "number": 6, "text": "Manchmal zeigt sich der Alarm zum Beispiel so:\nHerzrasen vor bestimmten Gesprächen.\n Flache oder angespannte Atmung.\n Ein Druckgefühl im Brustkorb.\nGedanken, die plötzlich schneller werden.\n Innere Unruhe ohne klaren Grund.\nSchlechter Schlaf vor Begegnungen.\n Ein Ziehen im Bauch."}]}};
    const bookDialog = document.getElementById('book-preview');
    let activeBook = null, bookIndex = 0, sampleOpener = null;
    const reduceBookMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
    let bookTurning = false;
    function renderBook() {
      const book = sampleBooks[activeBook], page = book.pages[bookIndex];
      document.getElementById('book-title').textContent = book.title;
      const img = document.getElementById('book-page');
      img.src = page.src;
      img.alt = book.title + ' – Originalseite ' + page.number;
      document.getElementById('book-text').textContent = page.text;
      document.getElementById('book-position').textContent = 'Seite ' + (bookIndex + 1) + ' von ' + book.pages.length;
      document.getElementById('book-prev').disabled = bookIndex === 0;
      document.getElementById('book-next').disabled = bookIndex === book.pages.length - 1;
      [bookIndex + 1, bookIndex - 1].forEach(i => { if (book.pages[i]) { const preload = new Image(); preload.src = book.pages[i].src; } });
    }
    function makeLeaf(src, direction) {
      const leaf = document.createElement('div');
      leaf.className = 'book-leaf ' + direction;
      leaf.setAttribute('aria-hidden', 'true');
      const front = document.createElement('div');
      front.className = 'leaf-front';
      const frontImg = document.createElement('img');
      frontImg.src = src; frontImg.alt = '';
      front.append(frontImg);
      const back = document.createElement('div');
      back.className = 'leaf-back';
      const backImg = document.createElement('img');
      backImg.src = src; backImg.alt = '';
      back.append(backImg);
      leaf.append(front, back);
      return leaf;
    }
    function turnBook(step) {
      if (!activeBook || bookTurning) return;
      const pages = sampleBooks[activeBook].pages, next = bookIndex + step;
      if (next < 0 || next >= pages.length) return;
      const paper = bookDialog.querySelector('.book-paper');
      if (reduceBookMotion.matches) { bookIndex = next; renderBook(); return; }
      bookTurning = true;
      const forward = step > 0;
      const leaf = makeLeaf(pages[forward ? bookIndex : next].src, forward ? 'forward' : 'backward');
      paper.classList.add('is-turning', forward ? 'turn-forward' : 'turn-backward');
      paper.append(leaf);
      if (forward) { bookIndex = next; renderBook(); }
      const finish = () => {
        if (!forward) { bookIndex = next; renderBook(); }
        leaf.remove();
        paper.classList.remove('is-turning', 'turn-forward', 'turn-backward');
        bookTurning = false;
      };
      leaf.addEventListener('animationend', finish, {once: true});
      setTimeout(() => { if (bookTurning && leaf.isConnected) finish(); }, 1400);
    }
    document.querySelectorAll('[data-sample]').forEach(button => button.addEventListener('click', () => {
      sampleOpener = button; activeBook = button.dataset.sample; bookIndex = 0;
      bookDialog.querySelector('details').open = false; renderBook(); bookDialog.showModal(); bookDialog.scrollTop = 0;
    }));
    bookDialog.querySelector('.book-close').addEventListener('click', () => bookDialog.close());
    bookDialog.addEventListener('close', () => { if (sampleOpener) sampleOpener.focus(); });
    document.getElementById('book-prev').addEventListener('click', () => turnBook(-1));
    document.getElementById('book-next').addEventListener('click', () => turnBook(1));
    document.addEventListener('keydown', event => {
      if (!bookDialog.open) return;
      if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') { event.preventDefault(); turnBook(event.key === 'ArrowRight' ? 1 : -1); }
    });
    let touchStart = null;
    const bookStage = bookDialog.querySelector('.book-stage');
    bookStage.addEventListener('touchstart', event => { const t = event.changedTouches[0]; touchStart = {x:t.clientX,y:t.clientY}; }, {passive:true});
    bookStage.addEventListener('touchend', event => {
      if (!touchStart) return;
      const t = event.changedTouches[0], dx = t.clientX - touchStart.x, dy = t.clientY - touchStart.y;
      if (Math.abs(dx) > 45 && Math.abs(dx) > Math.abs(dy)) turnBook(dx < 0 ? 1 : -1);
      touchStart = null;
    }, {passive:true});


    document.querySelectorAll('.w3f-form').forEach(form => {
      const status = form.querySelector('.form-status');
      form.addEventListener('submit', async event => {
        event.preventDefault();
        if (!form.reportValidity()) return;
        if (form.elements.message && (!form.elements.name.value.trim() || !form.elements.message.value.trim())) {
          status.textContent = 'Bitte gib deinen Namen und eine Nachricht ein.';
          return;
        }
        const button = form.querySelector('button[type="submit"]');
        button.disabled = true;
        status.textContent = 'Wird gesendet …';
        try {
          const response = await fetch(form.action, {
            method: 'POST',
            headers: {'Content-Type': 'application/json', 'Accept': 'application/json'},
            body: JSON.stringify(Object.fromEntries(new FormData(form)))
          });
          const result = await response.json();
          if (!response.ok || !result.success) throw new Error(result.message || 'Fehler');
          form.reset();
          status.textContent = form.dataset.success;
        } catch (error) {
          status.textContent = 'Das hat leider nicht geklappt. Versuch es bitte später noch einmal oder schreib mir direkt an kleinfranziska90@gmail.com.';
        } finally {
          button.disabled = false;
        }
      });
    });


    document.querySelectorAll('.netlify-form').forEach(form => {
      const status = form.querySelector('.form-status');
      form.addEventListener('submit', async event => {
        event.preventDefault();
        if (!form.reportValidity()) return;
        if (!form.elements.name.value.trim() || !form.elements.message.value.trim()) {
          status.textContent = 'Bitte gib deinen Namen und eine Nachricht ein.';
          return;
        }
        const button = form.querySelector('button[type="submit"]');
        button.disabled = true;
        status.textContent = 'Wird gesendet …';
        const onNetlify = location.hostname === 'innenleben.netlify.app' || location.hostname.endsWith('--innenleben.netlify.app');
        try {
          const response = await fetch(onNetlify ? '/' : form.dataset.endpoint, {
            method: 'POST',
            mode: onNetlify ? 'same-origin' : 'no-cors',
            headers: {'Content-Type': 'application/x-www-form-urlencoded'},
            body: new URLSearchParams(new FormData(form)).toString()
          });
          if (onNetlify && !response.ok) throw new Error('Fehler');
          form.reset();
          status.textContent = form.dataset.success;
        } catch (error) {
          status.textContent = 'Das hat leider nicht geklappt. Versuch es bitte später noch einmal oder schreib mir direkt an kleinfranziska90@gmail.com.';
        } finally {
          button.disabled = false;
        }
      });
    });


    const pauseLine = document.querySelector('.pause');
    if (pauseLine && !window.matchMedia('(prefers-reduced-motion: reduce)').matches && 'IntersectionObserver' in window) {
      const text = pauseLine.textContent.trim();
      pauseLine.setAttribute('aria-label', text);
      pauseLine.textContent = '';
      let step = 0;
      text.split(/\s+/).forEach((word, index, words) => {
        const span = document.createElement('span');
        span.className = 'pause-word';
        span.setAttribute('aria-hidden', 'true');
        span.textContent = word;
        span.style.setProperty('--i', step);
        pauseLine.append(span);
        if (index < words.length - 1) pauseLine.append(' ');
        step += /[.!?]$/.test(word) ? 3 : 1;
      });
      pauseLine.classList.add('pause-waiting');
      const pauseObserver = new IntersectionObserver(entries => {
        if (entries.some(entry => entry.isIntersecting)) {
          pauseLine.classList.add('pause-visible');
          pauseObserver.disconnect();
        }
      }, {threshold: 0.6});
      pauseObserver.observe(pauseLine);
    }

    const motionPreference = window.matchMedia('(prefers-reduced-motion: reduce)');
    const heroVideo = document.querySelector('.hero-video');
    if (heroVideo) {
      const syncHeroVideo = () => {
        if (motionPreference.matches) { heroVideo.pause(); heroVideo.removeAttribute('autoplay'); }
        else { heroVideo.play().catch(() => {}); }
      };
      syncHeroVideo();
      motionPreference.addEventListener('change', syncHeroVideo);
    }
    if (!motionPreference.matches && 'IntersectionObserver' in window) {
      const photoObserver = new IntersectionObserver(entries => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.remove('awaiting-view');
            photoObserver.unobserve(entry.target);
          }
        });
      }, {threshold: 0.12});
      document.querySelectorAll('main .editorial-photo, #inhalt .editorial-photo').forEach(photo => {
        if (photo.closest('.still-life')) return;
        photo.classList.add('motion-photo', 'awaiting-view');
        photoObserver.observe(photo);
      });
      motionPreference.addEventListener('change', () => {
        if (motionPreference.matches) {
          photoObserver.disconnect();
          document.querySelectorAll('.awaiting-view').forEach(photo => photo.classList.remove('awaiting-view'));
        }
      });
    }

    const tabs = [...document.querySelectorAll('[role="tab"]')];
    function activate(tab) {
      tabs.forEach(item => {
        const selected = item === tab;
        item.setAttribute('aria-selected', String(selected));
        item.tabIndex = selected ? 0 : -1;
        const panel = document.getElementById(item.getAttribute('aria-controls'));
        panel.hidden = !selected;
        panel.classList.remove('panel-arriving');
        if (selected && !motionPreference.matches) {
          void panel.offsetWidth;
          panel.classList.add('panel-arriving');
        }
      });
    }
    tabs.forEach((tab, index) => {
      tab.addEventListener('click', () => activate(tab));
      tab.addEventListener('keydown', event => {
        let next;
        if (event.key === 'ArrowRight') next = (index + 1) % tabs.length;
        if (event.key === 'ArrowLeft') next = (index + tabs.length - 1) % tabs.length;
        if (event.key === 'Home') next = 0;
        if (event.key === 'End') next = tabs.length - 1;
        if (next !== undefined) { event.preventDefault(); activate(tabs[next]); tabs[next].focus(); }
      });
    });
    document.querySelectorAll('[data-dialog]').forEach(button => button.addEventListener('click', () => document.getElementById(button.dataset.dialog).showModal()));
    document.querySelectorAll('.close-dialog').forEach(button => button.addEventListener('click', () => button.closest('dialog').close()));
    function revealFragment() {
      const target = document.getElementById(decodeURIComponent(location.hash.slice(1)));
      const panel = target && target.closest('[role="tabpanel"]');
      if (panel) {
        activate(document.getElementById(panel.getAttribute('aria-labelledby')));
        target.scrollIntoView();
      }
    }
    window.addEventListener('hashchange', revealFragment);
    document.querySelectorAll('a[href^="#"]').forEach(link => link.addEventListener('click', () => setTimeout(revealFragment, 0)));
    revealFragment();
    document.getElementById('year').textContent = new Date().getFullYear();
  
    const betweenList = document.querySelector('.hero-between');
    if (betweenList && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      const betweenItems = [...betweenList.children];
      let betweenIndex = 0;
      betweenList.classList.add('is-rotating');
      betweenItems[0].classList.add('is-active');
      setInterval(() => {
        if (document.hidden) return;
        betweenItems[betweenIndex].classList.remove('is-active');
        betweenIndex = (betweenIndex + 1) % betweenItems.length;
        betweenItems[betweenIndex].classList.add('is-active');
      }, 4000);
    }

